using System;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshAffiliationsSnapshot(GameState p){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'clan',@clan::json,'guild',@guild::json)::text","prior",FreshAncientBossSnapshot(p),"clan",ClanCareerSnapshot(p),"guild",GuildFounderSnapshot(p)));}
    static byte[] FreshFounderFrame(uint npc,byte option,string name){var bytes=System.Text.Encoding.Default.GetBytes(name);var frame=new byte[28+bytes.Length];Revora.Network.Writer.WriteUInt16((ushort)(frame.Length-8),0,frame);Revora.Network.Writer.WriteUInt16(2032,2,frame);Revora.Network.Writer.WriteUInt32(npc,8,frame);frame[14]=option;frame[17]=(byte)bytes.Length;bytes.CopyTo(frame,18);System.Text.Encoding.ASCII.GetBytes("TQClient").CopyTo(frame,frame.Length-8);return frame;}
    static void FreshAffiliationsProcess(string phase){
        var p=FreshLoadSaved(true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);Require(!p.Fake && p.Account.State==AccountTable.AccountState.Player && !PirateFenced(p));
        if((bool)Sql("SELECT to_regclass('revora_fresh_affiliations_probe') IS NULL")){
            Require(phase.EndsWith("clan") && FreshAncientBossSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_ancient_boss_probe")) && p.Entity.ClanId==0 && p.Entity.GuildID==0);Sql("CREATE TABLE revora_fresh_affiliations_probe(stage text,snapshot text);INSERT INTO revora_fresh_affiliations_probe VALUES('new',@snapshot)","snapshot",FreshAffiliationsSnapshot(p));
        }
        Require(FreshAffiliationsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_affiliations_probe")));string stage=Convert.ToString(Sql("SELECT stage FROM revora_fresh_affiliations_probe"));var clan=FreshFounderFrame(9450,8,"FreshKeep");var guild=FreshFounderFrame(10003,2,"FreshBanner");
        if(phase.EndsWith("clan")){
            Require(stage=="new" && p.Entity.Money>=Config.ClanCreateGold);ulong silver=p.Entity.Money;uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;string items=Convert.ToString(Sql("SELECT json_agg(i ORDER BY uid)::text FROM items i WHERE entityid=@uid","uid",(long)p.Entity.UID));FreshClassicTalk(p,1002,9450,0);Revora.Network.PacketHandler.HandlePacket(clan,p);
            Require(p.Entity.ClanId!=0 && Kernel.Clans.ContainsKey(p.Entity.ClanId) && Kernel.Clans[p.Entity.ClanId].Members.ContainsKey(p.Entity.UID) && p.Entity.Money==silver-Config.ClanCreateGold && p.Entity.ConquerPoints==cp && p.Entity.RevoraPoint==rvp && items==Convert.ToString(Sql("SELECT json_agg(i ORDER BY uid)::text FROM items i WHERE entityid=@uid","uid",(long)p.Entity.UID)));Require(EntityTable.SaveEntity(p));string exact=FreshAffiliationsSnapshot(p);Revora.Network.PacketHandler.HandlePacket(clan,p);Require(exact==FreshAffiliationsSnapshot(p));Sql("UPDATE revora_fresh_affiliations_probe SET stage='clan',snapshot=@snapshot","snapshot",exact);System.Console.WriteLine("[fresh-affiliations] clan-silver="+Config.ClanCreateGold);
        }else if(phase.EndsWith("guild")){
            Require(stage=="clan" && p.Entity.ClanId!=0 && Kernel.Clans[p.Entity.ClanId].Members.ContainsKey(p.Entity.UID) && p.Entity.ConquerPoints>=Config.GuildCreateConquerPoints);uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;ulong silver=p.Entity.Money;FreshClassicTalk(p,1002,10003,9);Revora.Network.PacketHandler.HandlePacket(guild,p);
            Require(p.Entity.GuildID!=0 && p.Guild!=null && p.AsMember!=null && p.Entity.GuildRank==1000 && p.Guild.Members.ContainsKey(p.Entity.UID) && p.Guild.MemberCount==1 && p.Guild.SilverFund==500000 && p.Entity.ConquerPoints==cp-(uint)Config.GuildCreateConquerPoints && p.Entity.Money==silver && p.Entity.RevoraPoint==rvp);Require(EntityTable.SaveEntity(p));string exact=FreshAffiliationsSnapshot(p);Revora.Network.PacketHandler.HandlePacket(guild,p);Require(exact==FreshAffiliationsSnapshot(p));Sql("UPDATE revora_fresh_affiliations_probe SET stage='guild',snapshot=@snapshot","snapshot",exact);System.Console.WriteLine("[fresh-affiliations] guild-cp="+Config.GuildCreateConquerPoints);
        }else{
            Require(phase.EndsWith("reload") && stage=="guild" && p.Guild!=null && p.AsMember!=null && p.Entity.GuildRank==1000 && p.Guild.Members.ContainsKey(p.Entity.UID) && Kernel.Clans[p.Entity.ClanId].Members.ContainsKey(p.Entity.UID));FreshClassicTalk(p,1002,9450,0);string exact=FreshAffiliationsSnapshot(p);Revora.Network.PacketHandler.HandlePacket(clan,p);Require(exact==FreshAffiliationsSnapshot(p));FreshClassicTalk(p,1002,10003,9);exact=FreshAffiliationsSnapshot(p);Revora.Network.PacketHandler.HandlePacket(guild,p);Require(exact==FreshAffiliationsSnapshot(p));
        }
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=10304 AND source='clan-founder-v1' AND source_key=@clan","uid",(long)p.Entity.UID,"clan",p.Entity.ClanId.ToString())==1 && FreshAffiliationsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_affiliations_probe")) && !PirateFenced(p));System.Console.WriteLine("[career-process] "+phase+"-passed clan="+p.Entity.ClanId+" guild="+p.Entity.GuildID+" cp="+p.Entity.ConquerPoints+" silver="+p.Entity.Money);Server.CommandsAI("@close");throw new InvalidOperationException("Fresh affiliations did not close.");
    }
}
